// SparkMod V200: the player's starting castle (Spark castle2.mcstructure).
// One of the existing four Spark Castles is placed at the world's ORIGINAL spawn.
// The other three are still generated by world_structures_v183.js.
// World APIs are accessed only inside callbacks, not while modules import.
import {world,system} from '@minecraft/server';
import {terrainTop} from './terrain_v184.js';

const CASTLE='sparkmod:spark_castle';
const SIZE={x:40,y:30,z:40};
const SITE_KEY='sparkmod:v200_castle_spawn_site';
const PLACED_KEY='sparkmod:v200_castle_spawn_placed';
const LEVEL_KEY='sparkmod:v200_castle_spawn_y';
const ARRIVAL_TAG='sparkmod:v200_castle_first_arrival';
const GRAVEYARD_KEY='sparkmod:v192_spawn_graveyard_site';
const nearbyRange=100;
const arrivals=new Set();
let nextAttempt=0;

const safe=(f,otherwise)=>{try{return f();}catch(e){console.warn('[Spark Castle Spawn] '+String(e));return otherwise;}};
function overworld(){return world.getDimension('overworld');}
function getSite(){
 const saved=safe(()=>world.getDynamicProperty(SITE_KEY));
 if(typeof saved==='string'){
  const parsed=safe(()=>JSON.parse(saved));
  if(parsed&&Number.isFinite(parsed.x)&&Number.isFinite(parsed.z))return parsed;
 }
 // Must be captured BEFORE changing the default spawn.
 const p=safe(()=>world.getDefaultSpawnLocation());
 if(!p||!Number.isFinite(p.x)||!Number.isFinite(p.z))return null;
 const site={x:Math.floor(p.x),z:Math.floor(p.z)};
 safe(()=>world.setDynamicProperty(SITE_KEY,JSON.stringify(site)));
 // Preserve the V192 graveyard's original 300-block-east location.
 if(typeof safe(()=>world.getDynamicProperty(GRAVEYARD_KEY))!=='string'){
  safe(()=>world.setDynamicProperty(GRAVEYARD_KEY,JSON.stringify({x:site.x+300,z:site.z})));
 }
 return site;
}
function origin(site){return {x:site.x-20,z:site.z-20};}
function arriveAt(site,baseY){return {x:site.x+0.5,y:baseY+2,z:site.z+0.5};}
function validSpawnBlock(dim,p){
 const one=safe(()=>dim.getBlock({x:Math.floor(p.x),y:Math.floor(p.y),z:Math.floor(p.z)}));
 const two=safe(()=>dim.getBlock({x:Math.floor(p.x),y:Math.floor(p.y)+1,z:Math.floor(p.z)}));
 const floor=safe(()=>dim.getBlock({x:Math.floor(p.x),y:Math.floor(p.y)-2,z:Math.floor(p.z)}));
 return Boolean(one&&two&&floor&&one.isAir&&two.isAir&&!floor.isAir&&!floor.isLiquid);
}
function ensureSpawnAndPlayers(dim,site,baseY){
 const dest=arriveAt(site,baseY);
 if(!validSpawnBlock(dim,dest)){
  console.warn('[Spark Castle Spawn] Center not clear; waiting for the castle floor and air blocks.');
  return;
 }
 const before=safe(()=>world.getDefaultSpawnLocation());
 const changed=!before||Math.floor(before.x)!==site.x||Math.floor(before.z)!==site.z||Math.abs(before.y-dest.y)>1;
 if(changed)safe(()=>world.setDefaultSpawnLocation({x:site.x,y:dest.y,z:site.z}));
 for(const p of dim.getPlayers()){
  if(!arrivals.has(p.id)||p.hasTag(ARRIVAL_TAG))continue;
  const ok=safe(()=>{p.teleport(dest,{dimension:dim});return true;},false);
  if(!ok)continue;
  safe(()=>p.addTag(ARRIVAL_TAG));
  arrivals.delete(p.id);
  safe(()=>p.onScreenDisplay.setTitle('§6§lSPARK CASTLE',{subtitle:'§eWelcome to the Spark SMP!',fadeInDuration:10,stayDuration:55,fadeOutDuration:12}));
  safe(()=>p.sendMessage(`§6⚡ Your world spawn is inside Spark Castle! X: ${site.x}, Y: ${dest.y}, Z: ${site.z}`));
 }
}
function initializeCastle(){
 const site=getSite();if(!site)return;
 const dim=overworld();
 if(world.getDynamicProperty(PLACED_KEY)===true){
  const y=safe(()=>world.getDynamicProperty(LEVEL_KEY));
  if(typeof y==='number')ensureSpawnAndPlayers(dim,site,y);
  return;
 }
 // V232: new worlds no longer build a castle at world spawn - all Spark Castles are placed at
 // random plains spots by structures_v232.js. A spawn castle already built in an older world is kept.
 return;
 if(system.currentTick<nextAttempt)return;
 const near=dim.getPlayers().some(p=>Math.hypot(p.location.x-site.x,p.location.z-site.z)<nearbyRange);
 if(!near)return; // Castle chunks must be loaded first.
 const top=terrainTop(dim,{x:site.x,z:site.z});
 if(!top)return;
 const y=top.location.y+1;
 const o=origin(site);
 // Wait for all four corners of the 40x40 castle to be loaded.
 for(const x of [o.x,o.x+SIZE.x-1])for(const z of [o.z,o.z+SIZE.z-1]){
  if(!safe(()=>dim.getBlock({x,y,z})))return;
 }
 try{
  world.structureManager.place(CASTLE,dim,{x:o.x,y,z:o.z});
  // The user's source structure contains one authoring structure block at local (0,1,0).
  const marker=dim.getBlock({x:o.x,y:y+1,z:o.z});
  if(marker?.typeId==='minecraft:structure_block')marker.setType('minecraft:air');
  // Do not mark completion until the center is accessible.
  const dest=arriveAt(site,y);
  if(!validSpawnBlock(dim,dest))throw Error('Castle spawned but the central floor is not clear');
  world.setDynamicProperty(LEVEL_KEY,y);
  world.setDynamicProperty(PLACED_KEY,true);
  ensureSpawnAndPlayers(dim,site,y);
  for(const p of dim.getPlayers())if(Math.hypot(p.location.x-site.x,p.location.z-site.z)<nearbyRange)
   safe(()=>p.sendMessage('§aSpark Castle is ready. The world spawn is now inside it.'));
 }catch(e){
  console.warn('[Spark Castle Spawn] Will retry placement: '+e);
  nextAttempt=system.currentTick+100;
 }
}
world.afterEvents.playerSpawn.subscribe(({player,initialSpawn})=>{
 if(!initialSpawn)return;
 system.run(()=>{if(!safe(()=>player.hasTag(ARRIVAL_TAG),false))arrivals.add(player.id);});
});
system.runInterval(()=>safe(initializeCastle),20);
// Troubleshooting command: prints the castle position and generation status.
system.afterEvents.scriptEventReceive.subscribe(ev=>{
 if(ev.id!=='sparkmod:castle_spawn'||ev.sourceEntity?.typeId!=='minecraft:player')return;
 system.run(()=>{
  const site=getSite();if(!site)return ev.sourceEntity.sendMessage('§cCastle spawn not yet located.');
  const status=world.getDynamicProperty(PLACED_KEY)===true?'§aREADY':'§eWAITING FOR LOADED CHUNKS';
  ev.sourceEntity.sendMessage(`§6Spawn Castle X: ${site.x}, Z: ${site.z} ${status}`);
 });
});
